type OldOverwrite<TType, TWith> = TType extends any
  ? TWith extends any
    ? {
        [K in keyof TType | keyof TWith]: K extends keyof TWith
          ? TWith[K]
          : K extends keyof TType
          ? TType[K]
          : never;
      }
    : never
  : never;

type NewOverwrite<TType, TWith> = TType extends object
  ? TWith extends object
    ? {
        [K in keyof TType | keyof TWith]: K extends keyof TWith
          ? TWith[K]
          : K extends keyof TType
          ? TType[K]
          : never;
      }
    : TWith extends any
    ? TWith
    : never
  : TType extends any
  ? TWith extends any
    ? TWith
    : TType
  : never;

type Eq<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Assert<T extends true> = T;

// Case A: the bug from the commit message
export type A_old_string_string = Assert<Eq<OldOverwrite<string, string>, string>>; // expect FAIL
export type A_new_string_string = Assert<Eq<NewOverwrite<string, string>, string>>; // expect OK
// Case B: non-object TType replaced by TWith
export type B_new_string_number = Assert<Eq<NewOverwrite<string, number>, number>>; // expect OK
export type B_old_string_number = Assert<Eq<OldOverwrite<string, number>, number>>; // expect FAIL (commit msg says old gives 'number'?)
// Case C: object key-wise merge still works
export type C_new_obj = Assert<Eq<NewOverwrite<{ a: 1; b: 2 }, { b: 3 }>, { a: 1; b: 3 }>>; // expect OK
export type C_old_obj = Assert<Eq<OldOverwrite<{ a: 1; b: 2 }, { b: 3 }>, { a: 1; b: 3 }>>; // expect OK
// Case D: object TType, non-object TWith
export type D_new = Assert<Eq<NewOverwrite<{ a: 1 }, string>, string>>; // expect OK under new reading
export type D_old = Assert<Eq<OldOverwrite<{ a: 1 }, string>, string>>; // compare
// Case E: TWith unknown (middleware without input) against object TType
export type E_new = Assert<Eq<NewOverwrite<{ a: 1 }, unknown>, { a: 1 }>>; // expect FAIL if new yields unknown
export type E_old = Assert<Eq<OldOverwrite<{ a: 1 }, unknown>, { a: 1 }>>; // expect OK
// Case F: TWith undefined, object TType
export type F_new = Assert<Eq<NewOverwrite<{ a: 1 }, undefined>, { a: 1 }>>;
export type F_old = Assert<Eq<OldOverwrite<{ a: 1 }, undefined>, { a: 1 }>>;
// Case G: string TType, unknown TWith
export type G_new = Assert<Eq<NewOverwrite<string, unknown>, string>>;
export type G_old = Assert<Eq<OldOverwrite<string, unknown>, string>>;
// Case H: TType any
export type H_new = Assert<Eq<NewOverwrite<any, { a: 1 }>, { a: 1 }>>;
export type H_old = Assert<Eq<OldOverwrite<any, { a: 1 }>, { a: 1 }>>;
// Case I: TWith never
export type I_new = Assert<Eq<NewOverwrite<{ a: 1 }, never>, never>>;
export type I_old = Assert<Eq<OldOverwrite<{ a: 1 }, never>, { a: 1 }>>;
// Case J: TType never
export type J_new = Assert<Eq<NewOverwrite<never, { a: 1 }>, never>>;
EOF
